--
-- Name: current_tenant_is_authorized(uuid); Type: FUNCTION; Schema: app; Owner: neondb_owner
--

CREATE FUNCTION app.current_tenant_is_authorized(candidate_tenant_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT app.is_platform_admin()
    OR (
      candidate_tenant_id = app.current_tenant_id()
      AND EXISTS (
        SELECT 1 FROM public.memberships m
        WHERE m.id = app.current_membership_id()
          AND m.tenant_id = candidate_tenant_id
          AND m.user_id = app.current_user_id()
          AND m.status = 'active'
      )
    )
$$;


