--
-- Name: worker_claim_outbox(uuid, text, integer); Type: FUNCTION; Schema: app; Owner: neondb_owner
--

CREATE FUNCTION app.worker_claim_outbox(candidate_tenant_id uuid, owner text, event_limit integer) RETURNS SETOF public.transactional_outbox
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  RETURN QUERY
  WITH due AS (
    SELECT o.id
    FROM public.transactional_outbox AS o
    WHERE o.tenant_id = candidate_tenant_id
      AND o.status = 'pending'
      AND o.available_at <= now()
    ORDER BY o.created_at ASC
    LIMIT event_limit
    FOR UPDATE SKIP LOCKED
  )
  UPDATE public.transactional_outbox AS o
  SET status = 'leased',
      lease_owner = owner,
      attempts = o.attempts + 1
  FROM due
  WHERE o.id = due.id
  RETURNING o.*;
END;
$$;


ALTER FUNCTION app.worker_claim_outbox(candidate_tenant_id uuid, owner text, event_limit integer) OWNER TO neondb_owner;

