--
-- Name: worker_claim_tasks(uuid, text, integer); Type: FUNCTION; Schema: app; Owner: neondb_owner
--

CREATE FUNCTION app.worker_claim_tasks(candidate_tenant_id uuid, owner text, task_limit integer) RETURNS SETOF public.scheduled_tasks
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  RETURN QUERY
  WITH due AS (
    SELECT st.id
    FROM public.scheduled_tasks AS st
    WHERE st.tenant_id = candidate_tenant_id
      AND st.status = 'pending'
      AND st.available_at <= now()
    ORDER BY st.available_at ASC
    LIMIT task_limit
    FOR UPDATE SKIP LOCKED
  )
  UPDATE public.scheduled_tasks AS st
  SET status = 'leased',
      lease_owner = owner,
      lease_expires_at = now() + interval '120 seconds',
      attempts = st.attempts + 1,
      updated_at = now()
  FROM due
  WHERE st.id = due.id
  RETURNING st.*;
END;
$$;


