--
-- Name: memberships; Type: ROW SECURITY; Schema: public; Owner: neondb_owner
--

ALTER TABLE public.memberships ENABLE ROW LEVEL SECURITY;

--
-- Name: memberships memberships_bootstrap_insert; Type: POLICY; Schema: public; Owner: neondb_owner
--

CREATE POLICY memberships_bootstrap_insert ON public.memberships FOR INSERT WITH CHECK (((tenant_id = app.current_tenant_id()) AND (user_id = app.current_user_id()) AND (role = 'owner'::text) AND (status = 'active'::text) AND (NOT (EXISTS ( SELECT 1
   FROM public.memberships existing
  WHERE ((existing.tenant_id = memberships.tenant_id) AND (existing.status = 'active'::text)))))));


--
-- Name: memberships memberships_catalog_isolate; Type: POLICY; Schema: public; Owner: neondb_owner
--

CREATE POLICY memberships_catalog_isolate ON public.memberships USING (( SELECT app.current_tenant_is_authorized(memberships.tenant_id) AS current_tenant_is_authorized)) WITH CHECK (( SELECT app.current_tenant_is_authorized(memberships.tenant_id) AS current_tenant_is_authorized));


--
-- Name: memberships memberships_owner_insert; Type: POLICY; Schema: public; Owner: neondb_owner
--

CREATE POLICY memberships_owner_insert ON public.memberships FOR INSERT WITH CHECK (((tenant_id = app.current_tenant_id()) AND (EXISTS ( SELECT 1
   FROM public.memberships actor
  WHERE ((actor.id = app.current_membership_id()) AND (actor.user_id = app.current_user_id()) AND (actor.tenant_id = memberships.tenant_id) AND (actor.role = 'owner'::text) AND (actor.status = 'active'::text))))));


--
-- Name: memberships memberships_owner_update; Type: POLICY; Schema: public; Owner: neondb_owner
--

CREATE POLICY memberships_owner_update ON public.memberships FOR UPDATE USING (((tenant_id = app.current_tenant_id()) AND (EXISTS ( SELECT 1
   FROM public.memberships actor
  WHERE ((actor.id = app.current_membership_id()) AND (actor.user_id = app.current_user_id()) AND (actor.tenant_id = memberships.tenant_id) AND (actor.role = 'owner'::text) AND (actor.status = 'active'::text)))))) WITH CHECK ((tenant_id = app.current_tenant_id()));


--
-- Name: memberships memberships_select_self; Type: POLICY; Schema: public; Owner: neondb_owner
--

CREATE POLICY memberships_select_self ON public.memberships FOR SELECT USING ((app.is_platform_admin() OR ((user_id = app.current_user_id()) AND (status = 'active'::text))));


