--
-- Name: tenants; Type: ROW SECURITY; Schema: public; Owner: neondb_owner
--

ALTER TABLE public.tenants ENABLE ROW LEVEL SECURITY;

--
-- Name: tenants tenants_bootstrap_insert; Type: POLICY; Schema: public; Owner: neondb_owner
--

CREATE POLICY tenants_bootstrap_insert ON public.tenants FOR INSERT WITH CHECK (((id = app.current_tenant_id()) AND (app.current_user_id() IS NOT NULL) AND (NOT (EXISTS ( SELECT 1
   FROM public.memberships m
  WHERE ((m.user_id = app.current_user_id()) AND (m.status = 'active'::text)))))));


--
-- Name: tenants tenants_select_member; Type: POLICY; Schema: public; Owner: neondb_owner
--

CREATE POLICY tenants_select_member ON public.tenants FOR SELECT USING ((app.is_platform_admin() OR (EXISTS ( SELECT 1
   FROM public.memberships m
  WHERE ((m.tenant_id = tenants.id) AND (m.user_id = app.current_user_id()) AND (m.status = 'active'::text))))));


